add_action( 'woocommerce_thankyou', 'perfectpixel_thankyou_content_by_category', 5 );

function perfectpixel_thankyou_content_by_category( $order_id ) {
	$order      = wc_get_order( $order_id );
	$categories = wp_parse_id_list( '{{thankyou_category_ids}}' );
	if ( ! $order || ! $categories || $order->has_status( 'failed' ) ) {
		return;
	}
	foreach ( $order->get_items() as $item ) {
		if ( has_term( $categories, 'product_cat', $item->get_product_id() ) ) {
			echo '<div class="woocommerce-info perfectpixel-thankyou-category">' . wp_kses_post( do_shortcode( '{{thankyou_category_content}}' ) ) . '</div>';
			return;
		}
	}
}
